INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6344133, 938793, 117153, '<td valign="top">Love this shot, well done. The clarity is excellent, I would have cropped it off the bottom more to keep the bird in the bottom third, but otherwise I really good capture.</td>', 'Love this shot, well done. The clarity is excellent, I would have cropped it off the bottom more to keep the bird in the bottom third, but otherwise I really good capture.', '2011-03-07 13:02:02.000000', NULL, 1),
(6344141, 938741, 117153, '<td valign="top">Nice interesting shot, a little grainy - would have been nice with darker blue tones in the sky, more contrast would have made the clouds pop more. But I like it - well done :)</td>', 'Nice interesting shot, a little grainy - would have been nice with darker blue tones in the sky, more contrast would have made the clouds pop more. But I like it - well done :)', '2011-03-07 13:11:44.000000', NULL, 1),
(6344143, 938639, 117153, '<td valign="top">Great image, really nice detail on the first and second hill. Very peaceful.</td>', 'Great image, really nice detail on the first and second hill. Very peaceful.', '2011-03-07 13:12:44.000000', NULL, 1),
(6344146, 938841, 117153, '<td valign="top">A bit noisy, but the contrast adds to the shot and makes a really interesting image.</td>', 'A bit noisy, but the contrast adds to the shot and makes a really interesting image.', '2011-03-07 13:13:52.000000', NULL, 1),
(6344149, 938819, 117153, '<td valign="top">Made me laugh...looks like you went to a lot of trouble. Good composition, nice and clear.</td>', 'Made me laugh...looks like you went to a lot of trouble. Good composition, nice and clear.', '2011-03-07 13:16:50.000000', NULL, 1),
(6344157, 938849, 117153, '<td valign="top">When I first looked at this shot I didnt like it...but the more and longer I looked at it, the more I liked it. In fact I love it, I like that your focus on the sujects come out the top left and fades into the bottom right. Nice.</td>', 'When I first looked at this shot I didnt like it...but the more and longer I looked at it, the more I liked it. In fact I love it, I like that your focus on the sujects come out the top left and fades into the bottom right. Nice.', '2011-03-07 13:28:58.000000', NULL, 1),
(6344164, 938854, 117153, '<td valign="top">Nice subtle image, I like the shine of the cars against the matte sky.</td>', 'Nice subtle image, I like the shine of the cars against the matte sky.', '2011-03-07 13:33:04.000000', NULL, 1),
(6344169, 938825, 117153, '<td valign="top">Nice image, I would have cropped it more at the top and not so much at the bottom cutting off your focal point. But your image really stands out when you first take a look - well done.</td>', 'Nice image, I would have cropped it more at the top and not so much at the bottom cutting off your focal point. But your image really stands out when you first take a look - well done.', '2011-03-07 13:36:29.000000', NULL, 1),
(6344171, 938778, 117153, '<td valign="top">Nice contrast of the flowers against the sky, good composition, deeper tones in the sky would have enhanced your image, but I like it.</td>', 'Nice contrast of the flowers against the sky, good composition, deeper tones in the sky would have enhanced your image, but I like it.', '2011-03-07 13:38:39.000000', NULL, 1),
(6344175, 938713, 117153, '<td valign="top">Better lighting on the orange would have enhanced your image and scored better, but I liked it when I first looked at it, great idea with a nice composition.</td>', 'Better lighting on the orange would have enhanced your image and scored better, but I liked it when I first looked at it, great idea with a nice composition.', '2011-03-07 13:39:47.000000', NULL, 1),
