(6344188, 938148, 117153, '<td valign="top">The crop is a little tight on the right, I would have liked to have seen the whole tree, but the composition is good and the tones in the sky are nice.</td>', 'The crop is a little tight on the right, I would have liked to have seen the whole tree, but the composition is good and the tones in the sky are nice.', '2011-03-07 13:45:35.000000', NULL, 1),
(6344190, 938656, 117153, '<td valign="top">Ouch!! the movement makes them look sharper, an interesting and different image.</td>', 'Ouch!! the movement makes them look sharper, an interesting and different image.', '2011-03-07 13:46:55.000000', NULL, 1),
